def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    freq = Counter(v for row in grid for v in row)
    bg = freq.most_common(1)[0][0]
    color = next(v for v in freq if v != bg)
    out = [row[:] for row in grid]
    # Fill interior gaps between repeated marker cells in columns.
    cm = [[r for r in range(h) if grid[r][c] == color] for c in range(w)]
    for c, rs in enumerate(cm):
        if len(rs) >= 3:
            for a, b in zip(rs, rs[1:]):
                for r in range(a + 1, b):
                    out[r][c] = 2
        elif len(rs) == 2 and rs[1] - rs[0] == 2:
            out[rs[0] + 1][c] = 2
    # Rows containing at least three markers have their horizontal span filled.
    for r in range(h):
        cs = [c for c in range(w) if grid[r][c] == color]
        if len(cs) >= 3:
            for c in range(min(cs), max(cs) + 1):
                if grid[r][c] == bg:
                    out[r][c] = 2
    return out

